CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY, username TEXT, first_name TEXT, balance BIGINT NOT NULL DEFAULT 0 CHECK(balance>=0), is_blocked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS servers(id BIGSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL,url TEXT NOT NULL,username TEXT NOT NULL,password_enc TEXT NOT NULL,panel_type TEXT NOT NULL DEFAULT 'pasarguard',active INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 100,created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT DEFAULT '',price BIGINT NOT NULL CHECK(price>=0),traffic_gb BIGINT NOT NULL CHECK(traffic_gb>=0),days INTEGER NOT NULL CHECK(days>=0),group_ids TEXT DEFAULT '[]',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 100);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),product_id BIGINT NOT NULL REFERENCES products(id),amount BIGINT NOT NULL,status TEXT NOT NULL,server_id BIGINT REFERENCES servers(id),remote_username TEXT,subscription_url TEXT,error TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS services(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),order_id TEXT UNIQUE NOT NULL REFERENCES orders(id),product_id BIGINT NOT NULL REFERENCES products(id),server_id BIGINT NOT NULL REFERENCES servers(id),remote_username TEXT NOT NULL,subscription_url TEXT,data_limit_bytes BIGINT NOT NULL DEFAULT 0,used_bytes BIGINT NOT NULL DEFAULT 0,expires_at TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deposits(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),amount BIGINT NOT NULL CHECK(amount>0),receipt_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,reviewed_at TEXT,reviewed_by BIGINT);
CREATE TABLE IF NOT EXISTS ledger(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),amount BIGINT NOT NULL,kind TEXT NOT NULL,ref TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS tickets(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_messages(id BIGSERIAL PRIMARY KEY,ticket_id BIGINT NOT NULL REFERENCES tickets(id),sender_id BIGINT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_roles(user_id BIGINT PRIMARY KEY,role TEXT NOT NULL DEFAULT 'operator',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_id BIGINT,action TEXT NOT NULL,target TEXT,details TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),gateway TEXT NOT NULL,provider_ref TEXT UNIQUE,amount BIGINT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',payload TEXT,created_at TEXT NOT NULL,paid_at TEXT);
CREATE TABLE IF NOT EXISTS service_events(id BIGSERIAL PRIMARY KEY,service_id BIGINT REFERENCES services(id),user_id BIGINT NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,payload TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_services_user ON services(user_id,status);
CREATE INDEX IF NOT EXISTS idx_deposits_status ON deposits(status);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status);
CREATE INDEX IF NOT EXISTS idx_ledger_user ON ledger(user_id,created_at);

CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS discount_codes(code TEXT PRIMARY KEY,percent INTEGER NOT NULL,usage_limit INTEGER NOT NULL DEFAULT 0,used_count INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,expires_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gift_codes(code TEXT PRIMARY KEY,amount BIGINT NOT NULL DEFAULT 0,days INTEGER NOT NULL DEFAULT 0,traffic_gb INTEGER NOT NULL DEFAULT 0,usage_limit INTEGER NOT NULL DEFAULT 1,used_count INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gift_redemptions(id BIGSERIAL PRIMARY KEY,code TEXT NOT NULL REFERENCES gift_codes(code),user_id BIGINT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(code,user_id));
CREATE TABLE IF NOT EXISTS resellers(user_id BIGINT PRIMARY KEY REFERENCES users(id),commission_percent INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS referrals(inviter_id BIGINT NOT NULL REFERENCES users(id),invitee_id BIGINT NOT NULL UNIQUE REFERENCES users(id),bonus_amount BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channel_settings(kind TEXT PRIMARY KEY,chat_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lottery_entries(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bot_buttons(btn_key TEXT PRIMARY KEY,label TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 100);
CREATE INDEX IF NOT EXISTS idx_gift_redemptions_user ON gift_redemptions(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_resellers_active ON resellers(active);
